package org.emransm.moviebox.phone;
import android.app.*;import android.content.*;import android.net.Uri;import android.view.View;
import androidx.test.core.app.ActivityScenario;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;
import org.json.*;import org.junit.Test;import org.junit.runner.RunWith;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.zip.*;
import static org.junit.Assert.*;import static org.emransm.moviebox.phone.PhoneMediaScenarios.*;
@RunWith(AndroidJUnit4.class) public class LibraryStorageScenarios {
 static Context owned(){Context target=InstrumentationRegistry.getInstrumentation().getTargetContext();File folder=new File(target.getCacheDir(),"library-owned-"+UUID.randomUUID());assertTrue(folder.mkdirs());return new ContextWrapper(target){public File getFilesDir(){return folder;}};}
 static byte[] bytes(String value){return value.getBytes(StandardCharsets.UTF_8);}static File disk(Context c){return new File(c.getFilesDir(),"library.json");}
 static void write(File target,byte[] bytes)throws Exception{try(FileOutputStream out=new FileOutputStream(target)){out.write(bytes);}}static byte[] read(File target)throws Exception{try(InputStream in=new FileInputStream(target);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
 static JSONObject title(String id)throws Exception{return new JSONObject().put("subjectId",id).put("subjectType",1).put("title","Owned backup "+id);}
 static JSONObject blank()throws Exception{return new JSONObject().put("list",new JSONObject()).put("history",new JSONObject()).put("settings",new JSONObject());}
 static JSONObject incoming(String id)throws Exception{JSONObject source=blank();source.getJSONObject("list").put(id,title(id));return LibraryBackup.parse(LibraryBackup.export(source));}
 @Test public void bothUnreadableFilesArePreservedBeforeConfirmedRecoveryAndCanBeExported()throws Exception{
  Context c=owned();byte[] bad=bytes("{broken-primary"),bak=bytes("broken-backup");write(disk(c),bad);write(new File(c.getFilesDir(),"library.json.bak"),bak);
  try{new Library(c);fail();}catch(Library.ReadFailure expected){}assertArrayEquals(bad,read(disk(c)));assertArrayEquals(bak,read(new File(c.getFilesDir(),"library.json.bak")));
  Map<String,byte[]> zipped=new HashMap<>();try(ZipInputStream zip=new ZipInputStream(new ByteArrayInputStream(Library.damagedArchive(c)))){ZipEntry e;while((e=zip.getNextEntry())!=null){ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[100];int n;while((n=zip.read(b))!=-1)out.write(b,0,n);zipped.put(e.getName(),out.toByteArray());}}assertArrayEquals(bad,zipped.get("library.json"));assertArrayEquals(bak,zipped.get("library.json.bak"));
  File archive=Library.recoverAfterConfirmation(c,incoming("restored"));assertArrayEquals(bad,read(new File(archive,"library.json")));assertArrayEquals(bak,read(new File(archive,"library.json.bak")));try(LibraryClose store=new LibraryClose(new Library(c))){assertTrue(store.library.contains(title("restored")));assertEquals(0,store.library.settings().length());assertFalse(store.library.data.getString("identity").isEmpty());}
 }
 static class LibraryClose implements AutoCloseable{final Library library;LibraryClose(Library l){library=l;}public void close(){library.close();}}
 @Test public void validAtomicBackupLoadsWithoutDestroyingCorruptPrimaryBeforeSave()throws Exception{Context c=owned();byte[] bad=bytes("corrupt");write(disk(c),bad);JSONObject good=blank();good.getJSONObject("list").put("safe",title("safe"));write(new File(c.getFilesDir(),"library.json.bak"),bytes(good.toString()));try(LibraryClose l=new LibraryClose(new Library(c))){assertTrue(l.library.contains(title("safe")));assertArrayEquals(bad,read(disk(c)));l.library.commitRestored(l.library.snapshot(),l.library.snapshot().toString());assertTrue(new JSONObject(new String(read(disk(c)),StandardCharsets.UTF_8)).getJSONObject("list").has("safe"));}}
 @Test public void structurallyInvalidLibraryFailsWithoutSilentlyReplacingSections()throws Exception{Context c=owned();byte[] original=bytes("{\"list\":[],\"history\":{},\"settings\":{}}");write(disk(c),original);try{new Library(c);fail();}catch(Library.ReadFailure expected){}assertArrayEquals(original,read(disk(c)));}
 @Test public void atomicRestorePreservesSettingsAndIdentityAndOldQueuedSavesCannotResurrect()throws Exception{Context c=owned();try(LibraryClose l=new LibraryClose(new Library(c))){Library store=l.library;store.settings().put("subtitleSize",28);store.toggle(title("old"));ExecutorService writer=(ExecutorService)field(store,"writer");CountDownLatch entered=new CountDownLatch(1),free=new CountDownLatch(1);writer.execute(()->{entered.countDown();try{free.await();}catch(InterruptedException ignored){}});assertTrue(entered.await(2,TimeUnit.SECONDS));try{store.save();JSONObject before=store.snapshot();LibraryBackup.MergeResult preview=LibraryBackup.merge(before,incoming("new"));store.commitRestored(preview.library,before.toString());assertEquals(before.getString("identity"),store.data.getString("identity"));assertEquals(28,store.settings().getInt("subtitleSize"));}finally{free.countDown();}writer.submit(()->{}).get(5,TimeUnit.SECONDS);JSONObject saved=new JSONObject(new String(read(disk(c)),StandardCharsets.UTF_8));assertTrue(saved.getJSONObject("list").has("new"));assertTrue(saved.getJSONObject("list").has("old"));}}
 @Test public void failedCommitAndStalePreviewKeepTheCurrentLibrary()throws Exception{Context c=owned();try(LibraryClose l=new LibraryClose(new Library(c))){Library store=l.library;store.toggle(title("keep"));((ExecutorService)field(store,"writer")).submit(()->{}).get();JSONObject before=store.snapshot(),candidate=LibraryBackup.merge(before,incoming("new")).library;assertTrue(disk(c).delete());assertTrue(disk(c).mkdir());File obstruction=new File(disk(c),"owned-obstruction");write(obstruction,bytes("keep"));try{store.commitRestored(candidate,before.toString());fail("Directory must not accept file commit");}catch(IOException expected){}assertEquals(before.toString(),store.snapshot().toString());assertTrue(obstruction.delete());assertTrue(disk(c).delete());write(disk(c),bytes(before.toString()));store.toggle(title("later"));try{store.commitRestored(candidate,before.toString());fail("Stale preview cannot replace later saves");}catch(IOException expected){}assertTrue(store.contains(title("later")));assertFalse(store.contains(title("new")));}}
 @Test public void oversizedProviderReadIsRejectedAndStreamClosed()throws Exception{boolean[] closed={false};InputStream input=new ByteArrayInputStream(new byte[2*1024*1024+1]){public void close()throws IOException{closed[0]=true;super.close();}};try{LibraryTransfer.readBackup(input);fail();}catch(IOException expected){}assertTrue(closed[0]);}
 static void clickConfirmation(String label)throws Exception{
  long until=System.currentTimeMillis()+5000;while(System.currentTimeMillis()<until){android.view.accessibility.AccessibilityNodeInfo root=InstrumentationRegistry.getInstrumentation().getUiAutomation().getRootInActiveWindow();if(root!=null)for(android.view.accessibility.AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(label)){if(!label.equalsIgnoreCase(String.valueOf(node.getText())))continue;for(int i=0;i<4&&node!=null;i++,node=node.getParent())if(node.isClickable()&&node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_CLICK))return;}Thread.sleep(100);}BlockFlowScenarios.capture("batch4-confirmation-failure.png");fail("Confirmation button missing: "+label);
 }
 static Uri document(){return Uri.parse("content://org.emransm.moviebox.phone.test.backup/owned-"+UUID.randomUUID()+".json");}
 static ContentResolver resolver(){return InstrumentationRegistry.getInstrumentation().getTargetContext().getContentResolver();}
 static void store(Uri uri,byte[] bytes)throws Exception{try(OutputStream out=resolver().openOutputStream(uri,"wt")){assertNotNull(out);out.write(bytes);}}
 static void result(ActivityScenario<PhoneActivity> s,int request,int code,Uri uri){main(s,a->call(a,"onActivityResult",new Class[]{int.class,int.class,Intent.class},request,code,new Intent().setData(uri)));}
 @Test public void documentProviderExportAndConfirmedRestoreMergeWithoutClearingExistingData()throws Exception{Uri uri=document();try(ActivityScenario<PhoneActivity> s=ActivityScenario.launch(PhoneActivity.class)){BlockFlowScenarios.isolate(s,new BlockFlowScenarios.FakeApi());main(s,a->{Library l=(Library)field(a,"library");l.toggle(title("existing"));call(a,"browse",new Class[]{String.class},"Settings");});result(s,LibraryTransfer.EXPORT,Activity.RESULT_OK,uri);waitFor(()->{try{return LibraryBackup.parse(LibraryTransfer.readBackup(resolver().openInputStream(uri))).getJSONArray("list").length()==1;}catch(Exception e){return false;}},5000);JSONObject exported=LibraryBackup.parse(LibraryTransfer.readBackup(resolver().openInputStream(uri)));assertEquals(1,exported.getJSONArray("list").length());store(uri,LibraryBackup.export(new JSONObject(blank().toString()).put("list",new JSONObject().put("added",title("added")))));result(s,LibraryTransfer.IMPORT,Activity.RESULT_OK,uri);clickConfirmation("Restore");waitFor(()->{boolean[] yes={false};main(s,a->yes[0]=((Library)field(a,"library")).contains(title("added")));return yes[0];},5000);main(s,a->{Library l=(Library)field(a,"library");assertTrue(l.contains(title("existing")));assertTrue(l.contains(title("added")));});BlockFlowScenarios.capture("batch4-restored-settings.png");}finally{resolver().delete(uri,null,null);}}
 @Test public void cancelRestoreAndCancelledPickerDoNotChangeSavedLibrary()throws Exception{Uri uri=document();store(uri,LibraryBackup.export(new JSONObject(blank().toString()).put("list",new JSONObject().put("cancelled",title("cancelled")))));try(ActivityScenario<PhoneActivity> s=ActivityScenario.launch(PhoneActivity.class)){BlockFlowScenarios.isolate(s,new BlockFlowScenarios.FakeApi());main(s,a->((Library)field(a,"library")).toggle(title("keep")));result(s,LibraryTransfer.IMPORT,Activity.RESULT_CANCELED,uri);result(s,LibraryTransfer.IMPORT,Activity.RESULT_OK,uri);clickConfirmation("Cancel");main(s,a->{Library l=(Library)field(a,"library");assertTrue(l.contains(title("keep")));assertFalse(l.contains(title("cancelled")));});}finally{resolver().delete(uri,null,null);}}
 @Test public void recoveryScreenExplainsPreservationAndResetNeedsExplicitConfirmation()throws Exception{
  try(ActivityScenario<PhoneActivity> s=ActivityScenario.launch(PhoneActivity.class)){
   BlockFlowScenarios.isolate(s,new BlockFlowScenarios.FakeApi());Library[] isolated={null};main(s,a->{isolated[0]=(Library)field(a,"library");put(a,"library",null);call(a,"showLibraryRecovery",new Class[]{});});
   try{BlockFlowScenarios.capture("batch4-recovery-screen.png");main(s,a->{assertTrue(BlockFlowScenarios.hasText((View)field(a,"root"),"Your saved data needs attention"));((LibraryTransfer)field(a,"libraryTransfer")).confirmReset();});clickConfirmation("Cancel");main(s,a->assertNull(field(a,"library")));}finally{main(s,a->put(a,"library",isolated[0]));}
  }
 }

 @Test public void closingHostDismissesOwnedDialogsAndConfirmedExportCanFinishSafely()throws Exception{
  Uri uri=document();ActivityScenario<PhoneActivity> s=ActivityScenario.launch(PhoneActivity.class);CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);LibraryTransfer[] transfer={null};ExecutorService[] worker={null};
  try{BlockFlowScenarios.isolate(s,new BlockFlowScenarios.FakeApi());main(s,a->{((Library)field(a,"library")).toggle(title("close-export"));transfer[0]=(LibraryTransfer)field(a,"libraryTransfer");worker[0]=(ExecutorService)field(transfer[0],"files");worker[0].execute(()->{entered.countDown();try{release.await();}catch(InterruptedException ignored){}});});assertTrue(entered.await(2,TimeUnit.SECONDS));result(s,LibraryTransfer.EXPORT,Activity.RESULT_OK,uri);main(s,a->assertEquals(1,((Set<?>)field(transfer[0],"dialogs")).size()));s.close();assertTrue(((Set<?>)field(transfer[0],"dialogs")).isEmpty());release.countDown();assertTrue(worker[0].awaitTermination(5,TimeUnit.SECONDS));JSONObject saved=LibraryBackup.parse(LibraryTransfer.readBackup(resolver().openInputStream(uri)));assertEquals("close-export",saved.getJSONArray("list").getJSONObject(0).getString("subjectId"));
  }finally{release.countDown();s.close();resolver().delete(uri,null,null);}
 }

}
